import{_ as o,a,c as n,ac as s}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"第二册：实践与进步 · 单元 1 语法总结 · 一般过去时与事件顺序至现在完成时与过去时间","description":"L1–L24 规则、例句、易错点。","frontmatter":{"title":"第二册：实践与进步 · 单元 1 语法总结 · 一般过去时与事件顺序至现在完成时与过去时间","description":"L1–L24 规则、例句、易错点。","splitFrom":"life/english/new-concept/book-2/unit-01/grammar.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第二册：实践与进步 · 单元 1 语法总结","summary":"L1–L24 规则、例句、易错点。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · 单元 1 语法总结","link":"/life/english/new-concept/book-2/unit-01/grammar"},"next":{"text":"第二册：实践与进步 · 单元 1 语法总结 · 冠词与可数性至间接引语与视角转换","link":"/life/english/new-concept/book-2/unit-01/grammar-part-02"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · 单元 1 语法总结","link":"/life/english/new-concept/book-2/unit-01/grammar"},"next":{"text":"第二册：实践与进步 · 单元 1 语法总结 · 冠词与可数性至间接引语与视角转换","link":"/life/english/new-concept/book-2/unit-01/grammar-part-02"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-01/grammar-part-01.md","filePath":"life/english/new-concept/book-2/unit-01/grammar-part-01.md"}'),t={name:"life/english/new-concept/book-2/unit-01/grammar-part-01.md"};function i(r,e,l,p,h,c){return a(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="第二册-实践与进步-·-单元-1-语法总结-·-一般过去时与事件顺序至现在完成时与过去时间" tabindex="-1">第二册：实践与进步 · 单元 1 语法总结 · 一般过去时与事件顺序至现在完成时与过去时间 <a class="header-anchor" href="#第二册-实践与进步-·-单元-1-语法总结-·-一般过去时与事件顺序至现在完成时与过去时间" aria-label="Permalink to &quot;第二册：实践与进步 · 单元 1 语法总结 · 一般过去时与事件顺序至现在完成时与过去时间&quot;">​</a></h1><p><a href="/life/english/new-concept/book-2/unit-01/grammar">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-2/unit-01/overview">单元导读</a> · <a href="/life/english/new-concept/book-2/unit-01/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-2/unit-01/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-2/unit-01/review">单元复习与自测</a></p><h2 id="第二册-实践与进步-·-单元-1-语法总结" tabindex="-1">第二册：实践与进步 · 单元 1 语法总结 <a class="header-anchor" href="#第二册-实践与进步-·-单元-1-语法总结" aria-label="Permalink to &quot;第二册：实践与进步 · 单元 1 语法总结 {#第二册-实践与进步-·-单元-1-语法总结}&quot;">​</a></h2><p><a href="/life/english/new-concept/book-2/unit-01/overview">单元导读</a> · <a href="/life/english/new-concept/book-2/unit-01/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-2/unit-01/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-2/unit-01/review">单元复习与自测</a></p><h2 id="一般过去时与事件顺序" tabindex="-1">一般过去时与事件顺序 <a class="header-anchor" href="#一般过去时与事件顺序" aria-label="Permalink to &quot;一般过去时与事件顺序 {#一般过去时与事件顺序}&quot;">​</a></h2><p>一般过去时把动作放在已经结束的过去时间内，肯定句用动词过去式；疑问和否定借助 did 后，实义动词恢复原形。be 的过去式是 was/were，不再加 did。叙事中连续的过去式通常按出现顺序推进情节；单凭一句过去式不能推断动作持续多久。先确定时间范围，再选择动词形式，不要把汉语中的“了”机械地翻译成完成时。本课应用：讲述已经结束的小冲突时，用过去式推进“听见、转身、离开”的动作，副词 quietly 修饰说话方式，而不是修饰说话者的身份。</p><p>一般过去时把动作放在已经结束的过去时间内，肯定句用动词过去式；疑问和否定借助 did 后，实义动词恢复原形。be 的过去式是 was/were，不再加 did。叙事中连续的过去式通常按出现顺序推进情节；单凭一句过去式不能推断动作持续多久。先确定时间范围，再选择动词形式，不要把汉语中的“了”机械地翻译成完成时。本课应用：at 配具体钟点，on 配某一天，in 配较大时间范围。叙述约会失败时，先交代约定时间，再给出发现问题的时刻。</p><p><strong>L1 原创例句：</strong> Maya closed her book quietly after the discussion.</p><p>讨论结束后，玛雅轻轻合上了书。</p><p><strong>L9 原创例句：</strong> The crowd reached the square at half past eight.</p><p>人群在八点半到达了广场。</p><p><strong>易错：</strong> quiet 是形容词，quietly 是副词；closed quiet 不能表达“轻轻合上”。</p><p>reach the square 不加 to；arrive at the square 才需要 at。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-001">Lesson 1</a> · <a href="/life/english/new-concept/book-2/unit-01/lesson-009">Lesson 9</a></p><h2 id="一般现在时与习惯" tabindex="-1">一般现在时与习惯 <a class="header-anchor" href="#一般现在时与习惯" aria-label="Permalink to &quot;一般现在时与习惯 {#一般现在时与习惯}&quot;">​</a></h2><p>一般现在时可以描述习惯、规律和当前相对稳定的状态。第三人称单数主语的实义动词通常加 -s；使用 does 或 does not 后，动词回到原形。频率副词常放在实义动词前、be 动词后，但句首句尾也有特定用法。正在发生的临时动作通常另用进行时，不能仅因句中出现 today 就自动选一般现在时或现在进行时。本课应用：usually 描述常态，不说明每一天都如此。主语 Leo 是第三人称单数时用 eats；换成 does 问句后 eat 恢复原形。</p><p>一般现在时可以描述习惯、规律和当前相对稳定的状态。第三人称单数主语的实义动词通常加 -s；使用 does 或 does not 后，动词回到原形。频率副词常放在实义动词前、be 动词后，但句首句尾也有特定用法。正在发生的临时动作通常另用进行时，不能仅因句中出现 today 就自动选一般现在时或现在进行时。本课应用：looks young 中 looks 是系动词，后接形容词 young；always 通常放在 looks 前，若谓语是 is 则通常放在 is 后。</p><p>一般现在时可以描述习惯、规律和当前相对稳定的状态。第三人称单数主语的实义动词通常加 -s；使用 does 或 does not 后，动词回到原形。频率副词常放在实义动词前、be 动词后，但句首句尾也有特定用法。正在发生的临时动作通常另用进行时，不能仅因句中出现 today 就自动选一般现在时或现在进行时。本课应用：has a habit 中 has 是实义动词“有”，疑问句通常借助 does；has hidden 中 has 是完成时助动词，疑问时直接提前。</p><p><strong>L2 原创例句：</strong> Leo usually eats breakfast before seven.</p><p>利奥通常七点前吃早餐。</p><p><strong>L17 原创例句：</strong> My aunt always looks cheerful before a performance.</p><p>我姑姑每次演出前看起来总是很愉快。</p><p><strong>L18 原创例句：</strong> Our dog often hides my bag under the sofa.</p><p>我们的狗经常把我的包藏在沙发下面。</p><p><strong>易错：</strong> He usually eat 不合主谓一致；He does usually eats 中不能重复标记第三人称单数。</p><p>looks cheerfully 若没有其他内容不能表达“看起来愉快”；此处用 cheerful。</p><p>Does the dog hides 错误；does 出现后使用 hide。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-002">Lesson 2</a> · <a href="/life/english/new-concept/book-2/unit-01/lesson-017">Lesson 17</a> · <a href="/life/english/new-concept/book-2/unit-01/lesson-018">Lesson 18</a></p><h2 id="动词、宾语与补足语" tabindex="-1">动词、宾语与补足语 <a class="header-anchor" href="#动词、宾语与补足语" aria-label="Permalink to &quot;动词、宾语与补足语 {#动词、宾语与补足语}&quot;">​</a></h2><p>英语陈述句通常先交代主语和谓语，再放宾语及必要的补足语。部分动词可以带人和物两个宾语，如 give somebody something，也可改为 give something to somebody；buy 常用 for。并不是所有动词都支持这两种结构，explain 通常用 explain something to somebody。补足语则进一步说明宾语的身份或状态，不能与表示地点和时间的附加信息混为一谈。本课应用：send 可以带“人＋物”双宾语，也可用“物＋to＋人”。当物品是代词 it 时，send it to me 更自然，避免机械保留所有双宾语次序。</p><p>英语陈述句通常先交代主语和谓语，再放宾语及必要的补足语。部分动词可以带人和物两个宾语，如 give somebody something，也可改为 give something to somebody；buy 常用 for。并不是所有动词都支持这两种结构，explain 通常用 explain something to somebody。补足语则进一步说明宾语的身份或状态，不能与表示地点和时间的附加信息混为一谈。本课应用：reply to 与 answer 的结构不同：reply to a message 必须保留 to，answer a message 可以直接接宾语。不要因中文都有“回复”就套同一结构。</p><p><strong>L3 原创例句：</strong> Nina sent her uncle a postcard from the island.</p><p>妮娜从岛上给叔叔寄了一张明信片。</p><p><strong>L22 原创例句：</strong> A walker replied to the message inside the bottle.</p><p>一位徒步者回复了瓶子里的留言。</p><p><strong>易错：</strong> send a postcard for her 表示替她寄，不一定表示寄给她；寄给她用 to her。</p><p>reply the message 通常应改为 reply to the message；answer the message 则不加 to。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-003">Lesson 3</a> · <a href="/life/english/new-concept/book-2/unit-01/lesson-022">Lesson 22</a></p><h2 id="现在完成时与过去时间" tabindex="-1">现在完成时与过去时间 <a class="header-anchor" href="#现在完成时与过去时间" aria-label="Permalink to &quot;现在完成时与过去时间 {#现在完成时与过去时间}&quot;">​</a></h2><p>现在完成时由 have/has 加过去分词构成，连接先前发生的事与现在的结果或经验。明确已经结束的时间，如 yesterday、last Friday，通常要求一般过去时；since 引出起点，for 引出持续长度。动作是否还在持续要结合动词含义判断，不能把所有完成时都译成“已经结束”。gone 通常表示去了尚未回，been 表示到过或已经回来。本课应用：描述“截至现在去过几处地方”用 has visited；补充上周的某次参观则换成 visited。两种时态能在同一段落中各负其责。</p><p>现在完成时由 have/has 加过去分词构成，连接先前发生的事与现在的结果或经验。明确已经结束的时间，如 yesterday、last Friday，通常要求一般过去时；since 引出起点，for 引出持续长度。动作是否还在持续要结合动词含义判断，不能把所有完成时都译成“已经结束”。gone 通常表示去了尚未回，been 表示到过或已经回来。本课应用：have received 强调已经收到的信息数量，而 receive every day 描述固定习惯。完成时中的 received 是过去分词，不是因为前面有过去时间。</p><p>现在完成时由 have/has 加过去分词构成，连接先前发生的事与现在的结果或经验。明确已经结束的时间，如 yesterday、last Friday，通常要求一般过去时；since 引出起点，for 引出持续长度。动作是否还在持续要结合动词含义判断，不能把所有完成时都译成“已经结束”。gone 通常表示去了尚未回，been 表示到过或已经回来。本课应用：has lent 说明已经发生且仍与当前相关的借出行为；borrow 的主语是借入者，lend 的主语是借出者，二者不能按中文“借”互换。</p><p><strong>L4 原创例句：</strong> Iris has visited three coastal towns this month.</p><p>这个月艾瑞丝已经游览了三座海滨小镇。</p><p><strong>L5 原创例句：</strong> Our studio has received six messages today.</p><p>我们的工作室今天已收到六条消息。</p><p><strong>L11 原创例句：</strong> Ravi has lent me his bicycle for the weekend.</p><p>拉维把自行车借给了我，供周末使用。</p><p><strong>易错：</strong> has visited yesterday 通常不合适；yesterday 明确结束的时间应配 visited。</p><p>receive 不等于 send；已收到用 have received，不要写 have receive。</p><p>borrow me a bicycle 通常不表示借给我；应说 lend me a bicycle。</p><p><a href="/life/english/new-concept/book-2/unit-01/lesson-004">Lesson 4</a> · <a href="/life/english/new-concept/book-2/unit-01/lesson-005">Lesson 5</a> · <a href="/life/english/new-concept/book-2/unit-01/lesson-011">Lesson 11</a></p>',53)])])}const u=o(t,[["render",i]]);export{g as __pageData,u as default};
